pub type Validator = fn(&Value) -> Result<(), Error>;
pub type MethodRule = (Validator, Validator, bool);
pub fn method(name: &str) -> Result<MethodRule, Error> {
    match name {
        "status" => Ok((|v| validate_node(1010, v), |v| validate_node(20, v), false)),
        "adapter.list" => Ok((
            |v| validate_node(1010, v),
            |v| validate_node(1065, v),
            false,
        )),
        "agent_run.invoke" => Ok((|v| validate_node(1012, v), |v| validate_node(1031, v), true)),
        "agent_run.get" => Ok((|v| validate_node(1016, v), |v| validate_node(15, v), false)),
        "agent_run.subscribe" => Ok((|v| validate_node(1019, v), |v| validate_node(15, v), false)),
        "agent_run.cancel" => Ok((|v| validate_node(1022, v), |v| validate_node(1034, v), true)),
        "agent_run.respond" => Ok((|v| validate_node(1025, v), |v| validate_node(1011, v), true)),
        "agent_run.native.respond" => {
            Ok((|v| validate_node(1028, v), |v| validate_node(1011, v), true))
        }
        _ => Err(Error::new("METHOD_NOT_FOUND")),
    }
}
